INSERT INTO alcovia.payments (razorpay_payment_id, paid_on, stream, plan, payment_type, amount_inr, invoice_id, workshop_id)
VALUES ('{{$json.razorpay_payment_id}}', '{{$json.paid_on}}', '{{$json.stream}}', '{{$json.plan}}', '{{$json.payment_type}}', {{$json.amount_inr}},
        NULLIF('{{$json.invoice_id}}', 'null'), NULLIF('{{$json.workshop_id}}', 'null'))
ON CONFLICT (razorpay_payment_id) DO NOTHING;
UPDATE alcovia.invoices SET status = 'Paid', paid_on = '{{$json.paid_on}}' WHERE invoice_id = NULLIF('{{$json.invoice_id}}', 'null');
